-- Restore per-expansion creature_classlevelstats (basehp0-4, damage bases, attack power).
-- Replaces OldContentBaseHP/CurrentContentBaseHP binary schema.
-- damage_exp4 uses historical MoP level floor averages / 3 where expansion damage was empty.

DROP TABLE IF EXISTS `creature_classlevelstats`;
CREATE TABLE `creature_classlevelstats` (
  `level` tinyint NOT NULL,
  `class` tinyint NOT NULL,
  `basehp0` mediumint unsigned NOT NULL DEFAULT 1,
  `basehp1` mediumint unsigned NOT NULL DEFAULT 1,
  `basehp2` mediumint unsigned NOT NULL DEFAULT 1,
  `basehp3` mediumint unsigned NOT NULL DEFAULT 1,
  `basehp4` mediumint unsigned NOT NULL DEFAULT 1,
  `basemana` mediumint unsigned NOT NULL DEFAULT 0,
  `basearmor` mediumint unsigned NOT NULL DEFAULT 1,
  `damage_base` float NOT NULL DEFAULT 0,
  `damage_exp1` float NOT NULL DEFAULT 0,
  `damage_exp2` float NOT NULL DEFAULT 0,
  `damage_exp3` float NOT NULL DEFAULT 0,
  `damage_exp4` float NOT NULL DEFAULT 0,
  `attackpower` mediumint unsigned NOT NULL DEFAULT 0,
  `rangedattackpower` mediumint unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`level`, `class`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM `creature_classlevelstats`;
